/**
 *  Which pass over the archive a [`Progress`] belongs to. The archive is read twice: once to hash it before anything is
 *  opened, once to extract it (hashed again as it goes), and each pass runs from 0 to the archive's size.
 */
export type Pass = 
/**  Hashing the whole archive against the manifest. Nothing is written yet. */
"verify" | 
/**  Extracting into the temporary directory. */
"unpack";

/**  Where the link to the gateway is. */
export type Phase = 
/**  Dialling, or waiting for the handshake. */
"connecting" | 
/**  Handshake done: frames flow. */
"ready" | 
/**  The link is down or failing; the host keeps trying. */
"degraded" | 
/**  The gateway cannot be used (too old, wrong protocol); the host stops until told to retry. */
"incompatible";

/**  A folder the user picked, in the form the local endpoint uses. */
export type PickedFolder = {
	/**  `~/projects/x` for a folder under the user's home, the absolute path otherwise. */
	path: string,
	/**  Whether `path` is relative to the home (starts with `~/`). */
	home_relative: boolean,
};

/**  The operating system. */
export type Platform = 
/**  Linux and the other Unix desktops. */
"linux" | 
/**  Windows. */
"windows" | 
/**  macOS. */
"macos" | 
/**  Anything else. */
"other";

/**  What the user asked for with `BOOPIS_RENDERER`. */
export type Policy = 
/**  The host's evidence-based rule. */
"auto" | 
/**  Touch nothing: `WebKitGTK`'s own choice. */
"default" | 
/**
 *  `WEBKIT_DMABUF_RENDERER_FORCE_SHM=1`: no `DMABUF`, frames copied through shared memory; GL compositing and GPU
 *  rasterisation stay.
 */
"shm" | 
/**  `WEBKIT_DISABLE_DMABUF_RENDERER=1`: no `DMABUF` and, in `WebKitGTK` 2.44 to 2.52, no GL either: CPU painting. */
"cpu" | 
/**  `__NV_DISABLE_EXPLICIT_SYNC=1`: the Wayland `Error 71` cure, keeps the `DMABUF` path. */
"nosync" | 
/**  `WEBKIT_DISABLE_COMPOSITING_MODE=1`: no accelerated compositing at all (the last resort). */
"software";

/**  The power profile, as far as the kernel says. `power-saver` is what halves `WebKit`'s rate. */
export type PowerProfile = 
/**  `low-power`: what `power-profiles-daemon` sets for its `power-saver` profile. */
"power_saver" | 
/**  `balanced`. */
"balanced" | 
/**  `performance`. */
"performance" | 
/**  A profile the firmware names differently (`quiet`, `cool`, `balanced-performance`). */
"other" | 
/**  No `platform_profile` on this machine, or it could not be read. */
"unknown";

/**  Where the machine gets its power. */
export type PowerSource = 
/**  A mains adapter is online. */
"ac" | 
/**  There is a mains adapter and none is online. */
"battery" | 
/**  No mains adapter is listed, or it could not be read: nothing is assumed. */
"unknown";

